def min_replacements_to_lucky_ticket(ticket):
    first_half_sum = int(ticket[:3])
    second_half_sum = int(ticket[3:])

    if first_half_sum == second_half_sum:
        return 0

    min_changes = float('inf')

    for i in range(10):
        for j in range(10):
            new_first_half_sum = first_half_sum - int(ticket[0]) + i
            new_second_half_sum = second_half_sum - int(ticket[3]) + j
            changes = abs(new_first_half_sum - new_second_half_sum)
            if changes % 2 == 0:
                min_changes = min(min_changes, changes // 2)

    return min_changes

